-- ongdalsaem — SAMPLE DATA (dev only): recipes for the sample dishes from sample_posts.sql.
-- Run after sample_posts.sql in the Supabase SQL Editor. Safe to re-run (plain updates on fixed ids).
-- Fills ingredients · steps · servings · cook time · difficulty on the 22 home-cooked samples
-- (004 Market bibimbap and 013 Street-stall pad thai are restaurant posts → no recipe, like the share flow).

update foods as f set ingredients = v.ingredients::jsonb, steps = v.steps::jsonb,
                      servings = v.servings, cook_minutes = v.minutes, difficulty = v.difficulty
from (values
  ('b0000000-0000-4000-8000-000000000001', 2, 25, 'easy',
   '[{"name": "Aged kimchi", "amount": "1 cup"}, {"name": "Pork belly", "amount": "100 g"}, {"name": "Tofu", "amount": "½ block"}, {"name": "Green onion", "amount": "1"}, {"name": "Gochugaru", "amount": "1 tsp"}, {"name": "Water", "amount": "400 ml"}]',
   '[{"text": "Fry the pork and kimchi until the edges caramelise."}, {"text": "Add water and gochugaru, then simmer.", "timer_sec": 900}, {"text": "Slide in the tofu and green onion, rest for 2 minutes.", "timer_sec": 120}]'),
  ('b0000000-0000-4000-8000-000000000002', 1, 15, 'easy',
   '[{"name": "Cooked rice", "amount": "1 bowl"}, {"name": "Spinach namul", "amount": "1 handful"}, {"name": "Bean sprout namul", "amount": "1 handful"}, {"name": "Carrot", "amount": "¼"}, {"name": "Egg", "amount": "1"}, {"name": "Gochujang", "amount": "1 tbsp"}, {"name": "Sesame oil", "amount": "1 tsp"}]',
