   '[{"text": "Simmer the anchovies and kelp in water for the broth.", "timer_sec": 900}, {"text": "Strain, season with soy sauce and add the sliced zucchini.", "timer_sec": 180}, {"text": "Boil the noodles, rinse in cold water and pour the hot broth over.", "timer_sec": 180}, {"text": "Top with egg ribbons and green onion."}]'),
  ('b0000000-0000-4000-8000-000000000003', 2, 15, 'easy',
