   '[{"text": "Squeeze the tofu, kimchi and blanched sprouts dry and chop finely."}, {"text": "Mix with the pork, garlic and soy sauce."}, {"text": "Fill and fold the wrappers."}, {"text": "Steam the dumplings.", "timer_sec": 600}]'),
